#!/usr/bin/env node
/**
 * student-auto: one student, the real path, and a proof that Auto picks the
 * true best schedule.
 *
 * The student story (run twice, desktop 1440x900 and phone 390x844, fresh
 * guest identity each time):
 *
 *   1. /connect - import a synthetic myUNT unofficial transcript PDF
 *      (fixtures/synthetic-transcript.pdf, generated by make-transcript.mjs;
 *      a made-up first-year CS student: MATH 1710, ENGL 1310, CSCE 1040),
 *      review the matched rows, click "Looks right".
 *   2. /courses - pick the Computer Science major, then press the tray's
 *      Auto and let it plan the next term's courses.
 *   3. /schedule (Week) - open Preferences: nothing before 10 AM, Fridays
 *      off, and two "Work" busy blocks painted onto the grid (Tuesday and
 *      Thursday, 5-9 PM). Then press Auto and wait for the other options.
 *   4. Walk every option Auto found, screenshot each, axe each, and check
 *      the grid shows no Friday meetings and no conflict markers. Details
 *      on option 1, then "Use this".
 *   5. Read the student's own storage: the planner state and the stored
 *      preferences, exactly what the Week page's optimizer request was
 *      built from.
 *
 * Then the solver (solver.ts, run with Bun against the app's own modules
 * and the reference solver) rebuilds that exact request and answers:
 *
 *   - does Auto (the app's engine, run on the same request) finish optimal;
 *   - does Auto's top pick cost exactly what the independent reference
 *     solver's top pick costs - the same schedule quality, from code the
 *     journey never copied;
 *   - are all of Auto's options feasible (reference violations()) and do
 *     they differ by at least the contract's minDifferentCourses;
 *   - did the applied plan (state.selectedSections) equal Auto's option 1.
 *
 * Section data is the recorded Spring 2027 capture the repo already ships
 * (frontend/tests/optimizer/scenarios/fixtures/spring-2027-trimmed.json),
 * served to the app through route interception; grades API is answered
 * unavailable. No network leaves the machine.
 *
 * Usage: node journey.mjs [baseURL] [outDir]
 * Env: UNTANGLE_BASE_URL, OUT_DIR, PLAYWRIGHT_MODULE, AXE_PATH, UNTANGLE_BUN
 */
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..", "..");
const base = process.env.UNTANGLE_BASE_URL ?? process.argv[2] ?? "http://127.0.0.1:3000";
const out = process.env.OUT_DIR ?? process.argv[3] ?? here;
mkdirSync(out, { recursive: true });

/* ───────── module loading (mirrors the courses-v2 journey) ───────── */

function loadModule(name, envPath) {
  const parent = createRequire(import.meta.url);
  try {
    return parent(name);
  } catch {
    if (envPath) return createRequire(join(envPath, "package.json"))(name);
    throw new Error(`${name} not found; set PLAYWRIGHT_MODULE / AXE_PATH to its install dir`);
  }
}
const { chromium } = loadModule("playwright", process.env.PLAYWRIGHT_MODULE);
const axePath =
  process.env.AXE_PATH ??
  (() => {
    try {
      return createRequire(import.meta.url).resolve("axe-core/axe.min.js");
    } catch {
      throw new Error("axe-core is not installed where the journey can resolve it; set AXE_PATH to axe.min.js or add axe-core at the repo root");
    }
  })();
const axeSource = readFileSync(axePath, "utf8");

function findBun() {
  if (process.env.UNTANGLE_BUN) return process.env.UNTANGLE_BUN;
  for (const candidate of ["/usr/local/bin/journey-bun", "/usr/local/bin/bun", "/home/user/.bun/bin/bun"]) {
    if (existsSync(candidate)) return candidate;
  }
  const probe = spawnSync("bun", ["--version"], { encoding: "utf8" });
  return probe.status === 0 ? "bun" : null;
}

/* ───────── checks and report ───────── */

const checks = [];
const notes = [];
const sectionRequests = []; // /api/sections/** calls that missed the recorded capture, across both viewports
function check(name, pass, detail) {
  checks.push({ name, pass, detail });
  console.log(`${pass ? "ok  " : "FAIL"} ${name}${detail ? ` - ${detail}` : ""}`);
  return pass;
}
const soft = (text) => notes.push(text);

let axeRuns = 0;
const axeFindings = [];

/* ───────── shared UI helpers (adapted from scheduler-v2, which drives this same app in CI) ───────── */

async function axe(page, context) {
  // Inline scripts execute synchronously and never fire load/error events, so
  // inject, then run axe in the same evaluate — no event to wait for.
  const found = await page.evaluate((source) => {
    if (typeof window.axe !== "object") {
      const script = document.createElement("script");
      script.textContent = source;
      document.head.appendChild(script);
    }
    if (typeof window.axe !== "object") throw new Error("axe did not load");
    return window.axe.run(document, { resultTypes: ["violations"] }).then(
      (result) =>
        result.violations.map((violation) => ({
          id: violation.id,
          impact: violation.impact,
          nodes: violation.nodes.length,
          sample: violation.nodes.slice(0, 3).map((node) => node.target.join(" ")),
        })),
      (error) => {
        throw new Error(`axe.run failed: ${error}`);
      },
    );
  }, axeSource);
  axeRuns += 1;
  axeFindings.push({ context, violations: found });
}

const main = (page) => page.getByRole("main");

async function openPrefs(page) {
  await main(page).getByRole("button", { name: /^Preferences/ }).click();
  const prefs = page.getByRole("dialog", { name: "Preferences" });
  await prefs.waitFor({ state: "visible" });
  return prefs;
}

async function closePrefs(prefs) {
  const page = prefs.page();
  await prefs.getByRole("button", { name: /close/i }).first().click().catch(() => {});
  await page.keyboard.press("Escape").catch(() => {});
  await prefs.waitFor({ state: "hidden", timeout: 5000 }).catch(() => {});
  if ((await prefs.count()) > 0) {
    await page.keyboard.press("Escape").catch(() => {});
    await page.getByRole("banner").getByRole("button", { name: "Close" }).click({ force: true }).catch(() => {});
  }
}

const atMinute = (box, minute) => box.y + ((minute - 480) / 840) * box.height;

async function paintWorkBlock(prefs, dayIndex, label) {
  const page = prefs.page();
  const grid = await prefs.getByRole("application").boundingBox();
  const x = grid.x + grid.width * ((dayIndex + 0.5) / 5);
  // Drag the centers of the 5:00 PM and 8:30 PM half-hours: the grid paints
  // through the landing cell, so this is exactly 5–9 PM.
  await page.mouse.move(x, atMinute(grid, 1035));
  await page.mouse.down();
  await page.mouse.move(x, atMinute(grid, 1245), { steps: 8 });
  await page.mouse.up();
  const name = prefs.getByRole("textbox", { name: "Name this busy time" });
  await name.waitFor({ state: "visible" });
  await name.fill("Work");
  await name.press("Enter");
  const item = prefs.getByRole("listitem").filter({ hasText: label });
  await item.first().waitFor({ state: "visible" });
  return item;
}

async function setEarliestStart(prefs, target) {
  const slider = prefs.getByRole("slider", { name: "Earliest class start" });
  await slider.waitFor({ state: "visible" });
  const read = async () => (await slider.getAttribute("aria-valuetext")) ?? (await slider.textContent()) ?? "";
  let value = await read();
  for (let i = 0; i < 8 && value !== target; i += 1) {
    await slider.press("ArrowDown");
    value = await read();
  }
  for (let i = 0; i < 8 && value !== target; i += 1) {
    await slider.press("ArrowUp");
    value = await read();
  }
  return value;
}

/* ───────── the student run for one viewport ───────── */

async function runViewport(context, name) {
  const viewDir = join(out, name);
  mkdirSync(viewDir, { recursive: true });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (error) => errors.push(String(error)));
  const shot = (file) => page.screenshot({ path: join(viewDir, file), fullPage: false });

  await page.goto(`${base}/connect`, { waitUntil: "load" });
  await page.getByText("Start with your transcript").waitFor({ state: "visible", timeout: 30000 });
  const fileInput = page.locator('input[type="file"]');
  await fileInput.waitFor({ state: "attached", timeout: 30000 });
  await axe(page, `${name}/connect`);
  await shot("01-connect.png");
  await fileInput.setInputFiles(join(here, "fixtures", "synthetic-transcript.pdf"));
  const looksRight = main(page).getByRole("button", { name: "Looks right" });
  await looksRight.waitFor({ state: "visible", timeout: 30000 });
  const reviewRegion = main(page).getByRole("region", { name: "Courses found" });
  const reviewRows = (await reviewRegion.locator("li").filter({ hasText: "Grade" }).allTextContents()).map((row) => row.replace(/\s+/g, " ").trim());
  await shot("02-review.png");
  // the synthetic transcript's exact completed record: code and the grade the row shows
  const transcript = [
    ["MATH 1710", "Grade B"],
    ["ENGL 1310", "Grade A"],
    ["CSCE 1040", "Grade A"],
  ];
  const imported = check(
    `${name}: transcript import matched the three completed courses`,
    reviewRows.length === 3 && transcript.every(([code, fact]) => reviewRows.some((row) => row.includes(code) && row.includes(fact))) && (await looksRight.isEnabled()),
    reviewRows.map((row) => row.slice(0, 40)).join(" | ") || "no graded rows",
  );
  await looksRight.click();

  // 2. Courses: choose the major, then tray Auto (Auto refuses to run without a major)
  await page.goto(`${base}/courses`, { waitUntil: "load" });
  await page.waitForLoadState("networkidle").catch(() => {});
  // Alpha (round five): before a major is chosen, Courses shows a pre-major
  // section beside the header degree button; both open the same dialog, and
  // the section unmounts once a major is picked. Use its button and assert
  // both halves of that behavior.
  const preMajor = page.getByRole("region", { name: "See your degree's courses" });
  await preMajor.waitFor({ state: "visible", timeout: 30000 });
  await preMajor.getByRole("button", { name: "Choose your major" }).click();
  const degree = page.getByRole("dialog", { name: "Your degree" });
  await degree.waitFor({ state: "visible", timeout: 30000 });
  await degree.getByRole("button", { name: "Computer Science" }).click();
  // Choosing may close the dialog by itself; Close only if it is still open.
  if (await degree.isVisible().catch(() => false)) {
    await degree.getByRole("button", { name: "Close" }).click({ timeout: 5000 }).catch(() => {});
    await degree.waitFor({ state: "hidden", timeout: 10000 }).catch(() => {});
  }
  const preMajorGone = !(await preMajor.isVisible().catch(() => false));
  check(
    `${name}: Courses drops the pre-major choose-a-major section once Computer Science is picked`,
    preMajorGone,
    preMajorGone ? "section hidden after choosing" : "section still visible after choosing",
  );
  await axe(page, `${name}/courses`);
  await shot("03-courses.png");
  const autoTray = page.getByRole("button", { name: "Auto", exact: true });
  await autoTray.waitFor({ state: "visible", timeout: 30000 });
  await autoTray.click();
  const result = page.locator('[data-flip="result"]:not([data-hidden])');
  await result.waitFor({ state: "visible", timeout: 30000 });
  const trayText = (await result.textContent()) ?? "";
  const trayRows = await page.locator('[data-flip^="tray:"]').allTextContents();
  await shot("04-tray-auto.png");
  const trayJoined = trayRows.map((row) => row.replace(/\s+/g, " ").trim()).join(" | ");
  check(
    `${name}: tray Auto planned CSCE 2100 and MATH 1720`,
    trayRows.length === 2 && trayJoined.includes("CSCE 2100") && trayJoined.includes("MATH 1720") && /Planned/.test(trayText),
    `${trayText.trim().slice(0, 40)} | ${trayJoined.slice(0, 100)}`,
  );
  soft(`${name}: tray result "${trayText.trim()}"; rows: ${trayRows.map((row) => row.trim().slice(0, 40)).join(" | ")}`);

  // 3. Week: preferences, then Auto
  await page.goto(`${base}/schedule`, { waitUntil: "load" });
  await main(page).waitFor({ state: "visible" });
  await page.locator('[data-event]').first().waitFor({ state: "visible", timeout: 30000 }).catch(() => {});
  await axe(page, `${name}/schedule-before`);
  await shot("05-week-before.png");

  // Alpha (round five): the first visit to Week opens the "Set up Auto" wizard
  // over the grid. Answer every question (answers save as they are given),
  // reach Ready, and close from there with Skip setup: finishing via Build my
  // week would run Auto itself and race this journey's own Auto proof. The
  // wizard must close and must not reopen on a return visit.
  const setup = page.getByRole("dialog", { name: "Set up Auto" });
  const setupOpen = await setup.isVisible().catch(() => false);
  check(`${name}: Week opens the Set up Auto wizard on first visit`, setupOpen, setupOpen ? "wizard visible over the grid" : "no wizard on first visit");
  if (setupOpen) {
    // Six steps: four questions, a Shape pane, then Ready. Advance while the
    // footer says Continue; on question steps pick the first answer first
    // (Continue stays disabled until an answer is picked). Stop at Ready
    // WITHOUT finishing: finishing via Build my week runs Auto itself and
    // would race this journey's own Auto proof.
    for (let step = 0; step < 8; step += 1) {
      const group = setup.getByRole("radiogroup");
      if (await group.isVisible().catch(() => false)) {
        await group.getByRole("radio").first().click();
      }
      const nextLabel = ((await setup.getByRole("button", { name: /^(Continue|Build my week|Done)$/ }).first().textContent()) ?? "").trim();
      if (/Build my week|Done/.test(nextLabel)) break;
      await setup.getByRole("button", { name: "Continue" }).click();
      await page.waitForTimeout(300);
    }
    await setup.getByText("What Auto will follow").waitFor({ state: "visible", timeout: 30000 });
    // Phone: the sheet header's Skip setup icon button. Desktop: the dialog's
    // own Close control (SetupAuto renders no Skip setup button there) - both
    // call dismiss(), which marks the setup seen without running Auto.
    await setup.getByRole("button", { name: name === "phone" ? "Skip setup" : "Close" }).click();
    await setup.waitFor({ state: "hidden", timeout: 10000 }).catch(() => {});
  }
  const setupClosed = !(await setup.isVisible().catch(() => false));
  await page.reload({ waitUntil: "load" });
  await main(page).waitFor({ state: "visible" });
  await page.locator("[data-event]").first().waitFor({ state: "visible", timeout: 30000 }).catch(() => {});
  const setupStaysClosed = !(await setup.isVisible().catch(() => false));
  check(
    `${name}: Set up Auto closes and does not reopen on return`,
    setupClosed && setupStaysClosed,
    setupClosed && setupStaysClosed ? "closed from Ready and still closed after a reload" : setupClosed ? "reopened after reload" : "never closed",
  );

  const prefs = await openPrefs(page);
  const sliderValue = await setEarliestStart(prefs, "10 AM");
  check(`${name}: nothing before 10 AM set`, sliderValue === "10 AM", sliderValue);
  await prefs.getByRole("button", { name: "Fridays off" }).click();
  await paintWorkBlock(prefs, 1, "Tue, 5–9 PM");
  await paintWorkBlock(prefs, 3, "Thu, 5–9 PM");
  await shot("06-prefs.png");
  await axe(page, `${name}/preferences`);
  await closePrefs(prefs);
  const summary = (await page.locator("#pref-summary").textContent()) ?? "";
  check(`${name}: summary shows the work blocks and Friday off`, /work Tue and Thu/.test(summary) && /Fridays off/.test(summary), summary.trim().slice(0, 140));

  const autoWeek = main(page).getByRole("button", { name: /^(Auto|Build)/ }).first();
  await autoWeek.click();
  const strip = page.getByRole("region", { name: "Other weeks Auto found" });
  await strip.waitFor({ state: "visible", timeout: 30000 });
  const countText = ((await strip.locator('[data-part="count"]').textContent()) ?? "").trim();
  const total = Number((countText.match(/1 of (\d+)/) ?? [])[1] ?? 0);
  check(`${name}: Auto found options to compare`, total > 0, countText);

  // 4. walk every option; the grid must stay feasible for the student's rules.
  // The strip swaps its count through an animation, so after every Next click
  // poll for the pill text to change — otherwise iteration 2+ can audit option
  // 1 while labelling it option 2.
  const count = strip.locator('[data-part="count"]').first();
  const readCount = () => count.textContent().then((text) => (text ?? "").trim());
  // each option's week as the browser renders it: per course, the sorted
  // "day time-range" strings the grid events show (the app's own timeRange),
  // comparable against the solver's rendered meetings rank by rank
  const weekOf = () =>
    page.evaluate(() => {
      const out = {};
      for (const el of document.querySelectorAll("[data-event]")) {
        const code = (el.getAttribute("data-key") ?? "").split("#")[0];
        const day = el.closest("[data-day]")?.getAttribute("data-day");
        if (!code || !day) continue;
        const time = [...el.querySelectorAll("span")].map((span) => span.textContent ?? "").find((text) => /\d{1,2}:\d{2}/.test(text)) ?? "";
        (out[code] ??= []).push(`${day} ${time}`);
      }
      for (const key of Object.keys(out)) out[key].sort();
      return out;
    });
  const optionChecks = [];
  for (let index = 1; index <= total; index += 1) {
    await axe(page, `${name}/option-${index}`);
    const fridayEvents = await page.locator('[data-day="Fri"] [data-event]').count();
    const conflicts = await page.locator('[data-event][data-conflict]').count();
    optionChecks.push({ index, fridayEvents, conflicts, week: await weekOf() });
    await shot(`07-option-${index}.png`);
    if (index < total) {
      const before = await readCount();
      await strip.getByRole("button", { name: "Next" }).click();
      const advanced = await page
        .waitForFunction(
          (prev) => {
            const text = (document.querySelector('[data-part="count"]')?.textContent ?? "").trim();
            return /\d+ of \d+/.test(text) && text !== prev;
          },
          before,
          { timeout: 5000 },
        )
        .then(() => true)
        .catch(() => false);
      if (!advanced) {
        throw new Error(`the option strip never left "${before}" after Next; auditing would relabel the same option`);
      }
    }
  }
  for (const [position, { index, fridayEvents, conflicts, week }] of optionChecks.entries()) {
    if (position > 0) {
      // a transition that never swapped the grid would relabel option i as
      // option i+1; the engine's diversity contract makes identical rendered
      // meetings across consecutive ranks impossible, so identical weeks fail
      check(
        `${name}: option ${index} renders different meetings than option ${index - 1}`,
        JSON.stringify(week) !== JSON.stringify(optionChecks[position - 1].week),
        "identical rendered meetings would mean the same option was audited twice",
      );
    }
    check(`${name}: option ${index} shows no Friday meetings`, fridayEvents === 0, `${fridayEvents} Friday events`);
    check(`${name}: option ${index} shows no conflicts`, conflicts === 0, `${conflicts} conflict-marked events`);
  }

  // details on option 1, then use it: walk back to option 1 by the strip's
  // count pill ([data-part="count"]), polling after every Next click
  let previous = await readCount();
  for (let index = 0; index < total; index += 1) {
    if (previous.startsWith("1 ")) break;
    await strip.getByRole("button", { name: "Next" }).click();
    await page
      .waitForFunction(
        (prev) => {
          const text = (document.querySelector('[data-part="count"]')?.textContent ?? "").trim();
          return /\d+ of \d+/.test(text) && text !== prev;
        },
        previous,
        { timeout: 5000 },
      )
      .catch(() => {});
    previous = await readCount();
  }
  await strip.getByRole("button", { name: "Details" }).click();
  await page.waitForTimeout(600);
  await shot("08-details-clicked.png");
  // the details surface is an <aside> labelled by its title on desktop, and on phones a
  // BottomSheet dialog that carries the title as aria-label (hasText would never match it)
  const panel = page.getByRole("complementary", { name: /Option 1 next to your week/ }).first().or(page.getByRole("dialog", { name: /Option 1 next to your week/ }).first());
  await panel.waitFor({ state: "visible", timeout: 15000 });
  const daysOnCampus = await panel.getByText("Days on campus").count();
  check(`${name}: details explain days on campus`, daysOnCampus > 0, `${daysOnCampus} mentions`);
  await page.getByRole("banner").getByRole("button", { name: "Close" }).click({ force: true }).catch(() => {});
  await page.keyboard.press("Escape").catch(() => {});
  // the planner store persists as { state, revision, savedAt } and every write
  // bumps the monotonic revision (planner-store.ts always saves
  // currentRevision + 1), so the applied option's save is observable as a
  // revision change. Read the base revision before the click, then poll for the
  // bump instead of sleeping a fixed 800 ms - a late or debounced save would
  // otherwise leave the capture reading tray-Auto's selectedSections, failing
  // appliedMatches and rebuilding the solver request from the old state.
  const baseRevision = await page.evaluate(() => {
    const raw = Object.entries(localStorage)
      .filter(([key]) => key.startsWith("untangle.planner-state.v1"))
      .map(([, value]) => value)[0];
    try {
      return JSON.parse(raw)?.revision ?? null;
    } catch {
      return null;
    }
  });
  await strip.getByRole("button", { name: "Use this" }).click();
  await page
    .waitForFunction(
      (base) =>
        Object.entries(localStorage)
          .filter(([key]) => key.startsWith("untangle.planner-state.v1"))
          .some(([, raw]) => {
            try {
              const doc = JSON.parse(raw);
              return typeof doc?.revision === "number" && doc.revision > base && Boolean(doc?.state?.selectedSections);
            } catch {
              return false;
            }
          }),
      baseRevision,
      { timeout: 10000 },
    )
    .catch(() => {});
  await shot("08-used.png");

  // 5. capture the student's own storage: what Auto's request was built from
  const captured = await page.evaluate(() => {
    const prefsEntries = Object.fromEntries(
      Object.entries(localStorage).filter(([key]) => key.startsWith("untangle-schedule-preferences:v2:")),
    );
    // the planner store persists in localStorage (it must survive reload), wrapped in a doc ({ state, revision, savedAt });
    // the solver takes the inner PlannerState
    const stateEntries = Object.entries(localStorage).filter(([key]) => key.startsWith("untangle.planner-state.v1"));
    const plannerState = stateEntries
      .map(([, raw]) => {
        try {
          return JSON.parse(raw)?.state ?? null;
        } catch {
          return null;
        }
      })
      .find(Boolean);
    return {
      state: plannerState ? JSON.stringify(plannerState) : null,
      prefsKey: Object.keys(prefsEntries)[0] ?? null,
      prefs: Object.values(prefsEntries)[0] ?? null,
    };
  });
  const state = JSON.parse(captured.state ?? "null");
  check(`${name}: applied plan stored sections`, Boolean(state?.selectedSections && Object.keys(state.selectedSections).length > 0), `${Object.keys(state?.selectedSections ?? {}).length} courses applied`);
  writeFileSync(join(viewDir, "state.json"), captured.state ?? "{}");
  writeFileSync(join(viewDir, "prefs.json"), captured.prefs ?? "{}");
  // the exact optimizer job Week Auto posted to its worker, for the solver to
  // compare against its rebuilt request
  const solverRequest = await page.evaluate(() => (window.__solverRequests ?? [])[0] ?? null);
  writeFileSync(join(viewDir, "worker-request.json"), JSON.stringify(solverRequest, null, 2));

  check(`${name}: no page errors`, errors.length === 0, errors.join("; ").slice(0, 200));
  await page.close();
  return { viewDir, countText, total, trayText, trayRows, state, prefsKey: captured.prefsKey, optionChecks };
}

/* ───────── the solver comparison for one run ───────── */

function runSolver(statePath, prefsPath, workerPath) {
  const bun = findBun();
  if (!bun) throw new Error("bun not found (set UNTANGLE_BUN); the solver needs it to import the app's optimizer");
  const run = spawnSync(bun, [join(here, "solver.ts"), "solve", statePath, prefsPath, workerPath], {
    cwd: repoRoot,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
  });
  if (run.status !== 0) throw new Error(`solver failed (${run.status}): ${run.stderr?.slice(0, 2000)}`);
  return JSON.parse(run.stdout);
}

function verifySolve(name, solve, uiTotal, optionChecks) {
  check(`${name}: solver enumerated a small request`, solve.combinations <= 150000, `${solve.combinations} combinations over ${solve.planCourses.join(", ")}`);
  check(`${name}: the request Week Auto sent matched the rebuilt one`, solve.workerRequestMatched === true, String(solve.workerRequestMatched));
  check(`${name}: Auto finished optimal`, solve.engine.status === "optimal", solve.engine.status);
  check(`${name}: the reference proved the request feasible`, solve.reference.feasible === true, String(solve.reference.feasible));
  check(
    `${name}: Auto's options cost what the reference's cost, rank by rank`,
    solve.engine.costs.length === solve.reference.costs.length && solve.engine.costs.every((cost, index) => cost === solve.reference.costs[index]),
    `engine ${solve.engine.costs.join(", ")} vs reference ${solve.reference.costs.join(", ")}`,
  );
  check(
    `${name}: Auto's top pick equals the true optimum`,
    solve.engine.costs[0] === solve.reference.costs[0],
    `engine ${solve.engine.costs[0]} vs optimum ${solve.reference.costs[0]}`,
  );
  check(
    `${name}: every Auto option is feasible`,
    [...solve.engine.options, ...solve.reference.options].every((option) => option.violations.length === 0),
    solve.engine.options.map((option) => option.violations.length).join(","),
  );
  check(
    `${name}: options differ by at least the contract minimum`,
    solve.optionPairDifferences.every((pair) => pair.differentCourses >= solve.reference.minDifferent),
    solve.optionPairDifferences.map((pair) => pair.differentCourses).join(", "),
  );
  check(
    `${name}: the contract minimum matches the reference`,
    solve.engine.minDifferentCourses === solve.reference.minDifferent,
    `${solve.engine.minDifferentCourses} vs ${solve.reference.minDifferent}`,
  );
  check(`${name}: the week offered what the engine returned`, uiTotal === solve.engine.options.length, `UI ${uiTotal} vs engine ${solve.engine.options.length}`);
  // each option on screen must be the engine's option, rank by rank: per course,
  // the sorted "day time-range" strings the grid shows (the app's own timeRange)
  // must equal the solver's rendered meetings for that rank's sections
  const canon = (list) => [...(list ?? [])].sort().join(" | ");
  const engineWeeks = solve.engine.options.map((option) => {
    const week = {};
    for (const section of option.sections) week[section.courseCode] = [...section.week].sort();
    return week;
  });
  const mismatches = optionChecks
    .map(({ index, week }, position) => {
      const engine = engineWeeks[position] ?? {};
      const wrong = [...new Set([...Object.keys(week), ...Object.keys(engine)])].filter((code) => canon(week[code]) !== canon(engine[code]));
      return { index, wrong, week, engine };
    })
    .filter(({ wrong }) => wrong.length > 0);
  check(
    `${name}: the browser's options match the engine's, rank by rank`,
    optionChecks.length === engineWeeks.length && mismatches.length === 0,
    mismatches
      .map(({ index, wrong, week, engine }) => `option ${index}: ${wrong.map((code) => `${code} browser [${(week[code] ?? []).join("; ")}] engine [${(engine[code] ?? []).join("; ")}]`).join(", ")}`)
      .join(" | ")
      .slice(0, 400),
  );
  return solve;
}

function appliedMatches(name, solve, state) {
  const applied = state?.selectedSections ?? {};
  const top = solve.engine.options[0]?.byCourse ?? {};
  const same =
    Object.keys(applied).length === Object.keys(top).length &&
    Object.keys(applied).every((code) => applied[code] === top[code]);
  check(`${name}: the applied plan is Auto's option 1`, same, `${JSON.stringify(applied)} vs ${JSON.stringify(top)}`);
}

/* ───────── run ───────── */

const report = { name: "student-auto", base, when: new Date().toISOString(), viewports: {}, checks, notes };

try {
  const bun = findBun();
  if (!bun) throw new Error("bun not found");
  // warm the section responses once: the same recorded capture the app is served
  const sectionsRun = spawnSync(bun, [join(here, "solver.ts"), "sections"], { cwd: repoRoot, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  if (sectionsRun.status !== 0) throw new Error(`solver sections failed: ${sectionsRun.stderr?.slice(0, 1000)}`);
  const sections = JSON.parse(sectionsRun.stdout);
  const responses = Object.entries(sections.responses);

  for (const [name, options] of [
    ["desktop", { viewport: { width: 1440, height: 900 } }],
    ["phone", { viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 }],
  ]) {
    const browser = await chromium.launch();
    const context = await browser.newContext({ baseURL: base, timezoneId: "America/Chicago", ...options });
    // record the optimizer job the Week page's Auto posts to its worker, so the
    // solver can prove its rebuilt request equals what the app actually sent
    await context.addInitScript(() => {
      window.__solverRequests = [];
      const post = Worker.prototype.postMessage;
      Worker.prototype.postMessage = function (message, ...rest) {
        try {
          if (message && typeof message === "object" && message.request && Array.isArray(message.request.courses)) {
            window.__solverRequests.push(JSON.parse(JSON.stringify(message)));
          }
        } catch {}
        return post.call(this, message, ...rest);
      };
    });
    // register the miss-recording 404 FIRST: Playwright gives the last-registered matching route
    // precedence, so the recorded capture below shadows it and only unseen section paths 404
    await context.route("**/api/sections/**", (route) => {
      sectionRequests.push(new URL(route.request().url()).pathname);
      return route.fulfill({ status: 404, json: { status: "unavailable" } });
    });
    // serve the recorded Spring 2027 capture; grades unavailable; nothing else leaves the machine
    for (const [path, body] of responses) await context.route(`**${path}`, (route) => route.fulfill({ json: body }));
    await context.route("**/api/grades/**", (route) =>
      route.fulfill({ json: { status: "unavailable", diagnostic: { kind: "not_in_fixture", title: "grades are not part of the recorded fixture" } } }),
    );

    const run = await runViewport(context, name);
    const solve = runSolver(join(run.viewDir, "state.json"), join(run.viewDir, "prefs.json"), join(run.viewDir, "worker-request.json"));
    writeFileSync(join(run.viewDir, "solve.json"), JSON.stringify(solve, null, 2));
    verifySolve(name, solve, run.total, run.optionChecks);
    appliedMatches(name, solve, run.state);
    report.viewports[name] = { ...run, solve: { planCourses: solve.planCourses, byCourse: solve.engine.options.map((option) => option.byCourse ?? {}), engineCosts: solve.engine.costs, refCosts: solve.reference.costs, combinations: solve.combinations, minDifferent: solve.reference.minDifferent } };
    await browser.close();
  }

  // repo convention (map-e2e, webmcp-e2e): serious or critical axe violations block;
  // everything found is reported in full so the app's a11y debt stays actionable
  const blocking = axeFindings.flatMap(({ context, violations }) =>
    violations.filter((violation) => violation.impact === "serious" || violation.impact === "critical").map((violation) => `${context}: ${violation.id}(${violation.nodes})`),
  );
  const reported = axeFindings
    .filter(({ violations }) => violations.length > 0)
    .map(({ context, violations }) => `${context}: ${violations.map((violation) => `${violation.id}[${violation.impact ?? "minor"}](${violation.nodes})`).join(", ")}`);
  check("axe: no serious or critical violations", blocking.length === 0, (blocking.length > 0 ? blocking : reported).join(" | "));
  report.axe = axeFindings;
  check("every section request matched the recorded capture", sectionRequests.length === 0, sectionRequests.join(", "));
} catch (error) {
  checks.push({ name: "journey crashed", pass: false, detail: String(error?.stack ?? error).slice(0, 2000) });
  console.error(error);
}

const failed = checks.filter((c) => !c.pass);
writeFileSync(join(out, "journey-report.json"), JSON.stringify(report, null, 2));
writeFileSync(
  join(out, "report.md"),
  [
    `# student-auto - ${report.when}`,
    "",
    `Student: synthetic first-year CS transcript (MATH 1710 B, ENGL 1310 A, CSCE 1040 A) ->`,
    `Computer Science major -> tray Auto -> Week preferences (nothing before 10 AM, Fridays off, Work Tue+Thu 5-9 PM) -> Auto.`,
    "",
    `Sections: frontend/tests/optimizer/scenarios/fixtures/spring-2027-trimmed.json (recorded from https://vsb.untgrades.app, 2026-10-15; upstream updated 2026-10-04).`,
    "",
    ...Object.entries(report.viewports).map(([name, run]) =>
      [
        `## ${name}`,
        "",
        `- Tray: ${run.trayText}`,
        `- Planned next term: ${run.solve.planCourses.join(", ")} (${run.solve.combinations} combinations)`,
        `- Auto options: ${run.countText}`,
        "",
        "| rank | Auto cost | reference cost | sections |",
        "|---|---|---|---|",
        ...run.solve.engineCosts.map((cost, index) => {
          const sections = Object.entries(run.solve.byCourse?.[index] ?? {}).map(([code, id]) => `${code.replace(" ", "")}=${id}`).join(" ");
          return `| ${index + 1} | ${cost} | ${run.solve.refCosts[index]} | ${sections} |`;
        }),
        "",
      ].join("\n"),
    ),
    `- minDifferentCourses: ${Object.values(report.viewports)[0]?.solve.minDifferent ?? "?"}`,
    "",
    ...(report.axe ?? []).some(({ violations }) => violations.length > 0)
      ? [
          "## axe findings (serious/critical block; all reported)",
          "",
          ...(report.axe ?? [])
            .filter(({ violations }) => violations.length > 0)
            .map(({ context, violations }) =>
              `- ${context}: ${violations.map((violation) => `${violation.id}[${violation.impact ?? "minor"}] on ${violation.nodes} node(s), e.g. ${violation.sample.join(" | ")}`).join("; ")}`,
            ),
          "",
        ]
      : [],
    `${checks.filter((c) => c.pass).length}/${checks.length} checks passed.`,
  ].join("\n"),
);

console.log(`\n${failed.length === 0 ? "ALL PASS" : "FAILURES"}: ${checks.filter((c) => c.pass).length}/${checks.length}`);
if (failed.length > 0) {
  for (const failure of failed) console.log(`  FAIL ${failure.name}: ${failure.detail}`);
  process.exit(1);
}
